package com.enfec.one.asset.notification; import com.enfec.one.asset.auth.SessionAuthService; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/notifications") public class NotificationController {private final NotificationRepository repo; private final SessionAuthService auth; public NotificationController(NotificationRepository repo,SessionAuthService auth){this.repo=repo;this.auth=auth;} @GetMapping public List<NotificationResponse> mine(@RequestHeader("X-Session-Id") String s){var u=auth.require(s);return repo.findByUsernameOrderByCreatedAtDesc(u.username()).stream().map(NotificationResponse::from).toList();} @PatchMapping("/{id}/read") public NotificationResponse read(@RequestHeader("X-Session-Id") String s,@PathVariable UUID id){var u=auth.require(s);var n=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Notification not found"));if(!u.username().equals(n.getUsername()))throw new IllegalArgumentException("Access denied");n.markRead();return NotificationResponse.from(repo.save(n));}}
